def IsMaximalAlgebraIdeal (I : Set A) : Prop :=
  IsAlgebraIdeal 𝕜 I ∧ I ≠ Set.univ ∧
    ∀ J : Set A, IsAlgebraIdeal 𝕜 J → I ⊆ J → J = I ∨ J = Set.univ

